config.script:
v = self.view
t = BlueRidge.Common.Util.extractQualifiedValues(v.custom.totals) or {}
d = BlueRidge.Common.Util.extractQualifiedValues(v.custom.draft) or {}
if not t.get("ticked") and not d.get("autoJoinEnabled"):
	BlueRidge.Common.Notify.toast("Nothing ticked", "Tick at least one row, or go back and keep adding new production.", "warning")
	return
v.custom.step = 3
